package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClonePair13410DifferenceFindingTest {

    private final ClonePair13410 subject = new ClonePair13410();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsDisagreeOnPermutedBytes() {
        // method1 only checks that every byte of the first array occurs somewhere in the second array,
        // whereas method2 compares the two arrays position by position.
        byte[] left = {0, 1};
        byte[] right = {1, 0};

        assertTrue(subject.method1(left, right));
        assertFalse(subject.method2(left, right));
    }
}
